    def is_pair(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2

    def pos(v, default=(0, 0)):
        if is_pair(v):
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def move_away(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def normalize_move(m):
        if not is_pair(m):
            return [0, 0]
        return [clamp_step(m[0]), clamp_step(m[1])]

    def candidates(src, target, avoid=None):
        sx, sy = src
        tx, ty = target
        moves = [[0, 0], [clamp_step(tx - sx), 0], [0, clamp_step(ty - sy)], [clamp_step(tx - sx), clamp_step(ty - sy)]]
        if avoid is not None and is_pair(avoid):
            ax, ay = avoid
            # Prefer moves that increase distance from avoid when close.
            if manhattan(src, (ax, ay)) <= 2:
                moves = sorted(moves, key=lambda m: manhattan((sx + m[0], sy + m[1]), (ax, ay)), reverse=True)
        return moves

    def best_item(src, items, prefer_far=False):
        best = None
        best_score = None
        for it in items or []:
            if is_pair(it):
                p = (it[0], it[1])
            elif isinstance(it, dict):
                p = pos(it.get("position") or it.get("pos") or it.get("cell"))
            else:
                continue
            score = manhattan(src, p)
            if best is None or (prefer_far and score > best_score) or ((not prefer_far) and score < best_score):
                best = p
                best_score = score
        return best

    def in_bounds(p, w, h):
        x, y = p
        return (w <= 0 or 0 <= x < w) and (h <= 0 or 0 <= y < h)

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    blocked = set()
    for key in ("walls", "obstacles", "blocked_cells", "occupied_cells"):
        for c in observation.get(key) or []:
            if is_pair(c):
                blocked.add((c[0], c[1]))

    def pick_valid(move_order):
